# A trie as nested dictionaries: one key per letter, "$" marks the end of a word.
words = [
    "program", "programmer", "progress", "project", "projector", "promise",
    "protocol", "process", "processor", "profile", "produce", "product",
    "compile", "compiler", "complete", "complex", "compute", "computer",
    "concat", "concurrent", "condition", "console", "constant", "context",
    "index", "inherit", "initial", "inline", "input", "insert", "inspect",
    "instance", "integer", "interface", "internal", "interpret",
    "parse", "parser", "partial", "pattern",
]

def insert(root, word):
    node = root
    for ch in word:
        node = node.setdefault(ch, {})   # follow the branch, or grow it
    node["$"] = 1

def count_nodes(node):
    return sum(1 + count_nodes(child) for key, child in node.items() if key != "$")

root = {}
for w in words:
    insert(root, w)

letters = sum(len(w) for w in words)
nodes = count_nodes(root)
print(f"{len(words)} words, {letters} letters typed in, only {nodes} trie nodes stored")
print(f"sharing saved {letters - nodes} nodes ({100 * (letters - nodes) / letters:.0f}%)")

nb["trie"] = {"words": words, "tree": root}

// Check the trie holds exactly the words, then count the sharing depth by depth.
const trie = nb.get('trie');
if (!trie) return 'Run the cell above that builds the trie first.';

function contains(tree, word) {
  let node = tree;
  for (const ch of word) {
    node = node[ch];
    if (!node) return false;
  }
  return !!node['$'];
}
function allWords(node, prefix, out) {
  if (node['$']) out.push(prefix);
  for (const k of Object.keys(node)) if (k !== '$') allWords(node[k], prefix + k, out);
  return out;
}

const missing = trie.words.filter(w => !contains(trie.tree, w));
const stored = allWords(trie.tree, '', []);
const extra = stored.filter(w => !trie.words.includes(w));
console.log('words found: ' + (trie.words.length - missing.length) + ' of ' + trie.words.length +
  (missing.length ? ' (missing: ' + missing.join(', ') + ')' : '') + '; words in the tree that should not be: ' + extra.length);

// nodes at each depth against letters at each position
const nodesAt = [], lettersAt = [];
(function count(node, depth) {
  for (const k of Object.keys(node)) {
    if (k === '$') continue;
    nodesAt[depth] = (nodesAt[depth] || 0) + 1;
    count(node[k], depth + 1);
  }
})(trie.tree, 0);
for (const w of trie.words) for (let i = 0; i < w.length; i++) lettersAt[i] = (lettersAt[i] || 0) + 1;

const letters = lettersAt.reduce((a, b) => a + b, 0), nodes = nodesAt.reduce((a, b) => a + b, 0);
console.log(letters + ' letters in the word list, ' + nodes + ' nodes in the trie: ' +
  (100 * (letters - nodes) / letters).toFixed(0) + '% saved');
console.log('first 3 letters: ' + lettersAt.slice(0, 3).join(', ') + ' letters, ' + nodesAt.slice(0, 3).join(', ') + ' nodes');
const byLetter = Object.keys(trie.tree).sort().map(k => k + ' ' + allWords(trie.tree[k], k, []).length);
console.log('words per first letter: ' + byLetter.join(', '));

const rows = [];
lettersAt.forEach((n, d) => {
  rows.push({ position: d + 1, count: n, what: 'letters in the word list' });
  rows.push({ position: d + 1, count: nodesAt[d] || 0, what: 'nodes in the trie' });
});
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Letters typed against nodes stored, by position in the word',
  data: { values: rows },
  mark: 'bar',
  encoding: {
    x: { field: 'position', type: 'ordinal', title: 'letter position (1 = first letter)' },
    xOffset: { field: 'what' },
    y: { field: 'count', type: 'quantitative', title: null },
    color: { field: 'what', type: 'nominal', title: null, scale: { range: ['#94a3b8', '#22d3ee'] } },
  },
};
